const item = $input.first().json;
const output = item.output || item;

// 1. Ekstrak Isi Teks Email (Body Text)
let emailBodyText = '';
if (typeof output === 'string') {
  const match = output.match(/EMAIL:\s*([\s\S]+)/i);
  emailBodyText = match ? match[1].trim() : output;
} else if (output?.properties?.full_email_text?.type) {
  // Format bersarang (seperti output saat ini)
  emailBodyText = output.properties.full_email_text.type;
} else if (output?.full_email_text) {
  // Format JSON bersih standar
  emailBodyText = output.full_email_text;
} else {
  emailBodyText = JSON.stringify(output);
}

// 2. Ekstrak Subjek Email (Mengambil opsi subject pertama)
let selectedSubject = '';
try {
  let rawSubjects = output?.properties?.subject_options?.items?.type || output?.subject_options;

  // Jika tersimpan sebagai string JSON array "[\"...\", \"...\"]"
  if (typeof rawSubjects === 'string' && rawSubjects.trim().startsWith('[')) {
    rawSubjects = JSON.parse(rawSubjects);
  }

  if (Array.isArray(rawSubjects) && rawSubjects.length > 0) {
    selectedSubject = rawSubjects[0];
  }
} catch (e) {
  // Ignore parsing error jika ada
}

// Fallback jika subject tidak ditemukan di JSON
if (!selectedSubject) {
  selectedSubject = `Shallot supply for ${item.clean_name || item.restaurant_name || 'your kitchen'}`;
}

// 3. Ekstrak Rekomendasi Grade (Grade S / Grade A)
const recommendedGrade = output?.properties?.recommended_grade?.type || output?.recommended_grade || '';

// 4. Konversi Baris Baru ke HTML yang Cantik & Rapi untuk Gmail
const emailBodyHtml = emailBodyText
  .split(/\n\s*\n/) // Pisahkan per paragraf
  .filter(p => p.trim())
  .map(p => `<p style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #222; margin-bottom: 14px;">${p.replace(/\n/g, '<br>')}</p>`)
  .join('');

// 5. Kembalikan data lengkap untuk Node Gmail / Email Sender
return [{
  json: {
    recipient_email: item.email || item.recipient_email,
    restaurant_name: item.clean_name || item.restaurant_name,
    recommended_grade: recommendedGrade,
    subject: selectedSubject,
    body_text: emailBodyText,
    body_html: emailBodyHtml
  }
}];
